#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> split(const std::string& line, char sep) {
    std::vector<std::string> fields;
    std::string current;
    for (char c : line) {
        if (c == sep) {
            fields.push_back(current);
            current.clear();
        } else {
            current += c;
        }
    }
    fields.push_back(current);
    return fields;
}

int main() {
    const std::vector<std::string> fields = split(",a,,b,", ',');
    std::cout << fields.size();
    for (const std::string& field : fields) {
        std::cout << " [" << field << ']';
    }
    std::cout << '\n';
}

#include <iostream>
#include <string>
#include <vector>

struct Entry {
    std::string word;
    int count;
};

int& tally(std::vector<Entry>& table, const std::string& word) {
    for (Entry& entry : table) {
        if (entry.word == word) {
            return entry.count;
        }
    }
    table.push_back(Entry{word, 0});
    return table.back().count;
}

int main() {
    std::vector<Entry> table;
    table.reserve(2);

    int& the = tally(table, "the");
    ++the;
    ++tally(table, "mat");
    ++tally(table, "sat");

    the += 10;
    std::cout << table.front().count << '\n';
}

