#include <cassert>
#include <cstddef>
#include <vector>

// Exactly one allocation: measure first, reserve once, then append.
std::vector<int> flatten(const std::vector<std::vector<int>>& chunks) {
    std::size_t total = 0;
    for (const std::vector<int>& chunk : chunks) {
        total += chunk.size();
    }

    std::vector<int> out;
    out.reserve(total);  // capacity only: size() is still 0 and no int
                         // has been constructed, so out[0] here would be UB.

    // reserve(n) guarantees no reallocation until size() exceeds n, so both
    // the block address and the capacity survive every push_back below.
    const std::size_t reserved = out.capacity();
    const int* const base = out.data();

    for (const std::vector<int>& chunk : chunks) {
        for (int value : chunk) {
            out.push_back(value);
        }
    }

    assert(out.size() == total);
    assert(out.capacity() == reserved);  // no growth event occurred
    assert(out.data() == base);          // so no handle was invalidated
    return out;
}

#include <cstddef>
#include <list>

struct Session {
    int id;
    long expires_ns;
    int hits;
};

// Contract: the caller holds Session* to sessions that survive the call.
// std::vector is disqualified -- erasing shifts every later element, so
// handles at and after the erased position go stale, and a later erase
// can also reallocate nothing but still move the survivors. Erasing a
// list node invalidates handles to that node only; every other Session*
// keeps working, because the surviving nodes never move.
std::size_t expire(std::list<Session>& sessions, long now_ns) {
    std::size_t removed = 0;
    for (auto it = sessions.begin(); it != sessions.end();) {
        if (it->expires_ns <= now_ns) {
            // erase returns the position after the erased node. Writing
            // erase(it) and then ++it would increment a dead iterator.
            it = sessions.erase(it);
            ++removed;
        } else {
            ++it;
        }
    }
    return removed;
}

#include <array>
#include <cstddef>
#include <string>

using Histogram = std::array<std::size_t, 256>;

// The braces value-initialise all 256 counters. A bare `Histogram counts;`
// local would leave every scalar element indeterminate, and ++counts[byte]
// would read one of them -- undefined behaviour.
Histogram byte_histogram(const std::string& text) {
    Histogram counts{};
    for (unsigned char byte : text) {  // plain char may be signed: a byte
        ++counts[byte];                // above 127 would index negatively
    }
    return counts;
}

// By reference: no 256-element copy, and unlike a built-in array parameter
// the type still carries the length, so no size has to be passed alongside.
std::size_t distinct_bytes(const Histogram& counts) {
    std::size_t distinct = 0;
    for (std::size_t count : counts) {
        if (count != 0) {
            ++distinct;
        }
    }
    return distinct;
}

// No allocation and no bookkeeping: the storage is the object.
static_assert(sizeof(Histogram) == 256 * sizeof(std::size_t));

#include <cstddef>
#include <deque>
#include <optional>
#include <string>
#include <utility>

struct Edit {
    std::size_t offset;
    std::string removed;
};

class UndoHistory {
public:
    explicit UndoHistory(std::size_t bound) : bound_{bound} {}

    // push_back and pop_front are O(1) and relocate nothing. End insertion
    // invalidates every iterator, but references and pointers to elements
    // that are still present stay valid -- that is what lets the editor
    // keep an Edit* to a retained entry across a record() call.
    void record(Edit edit) {
        edits_.push_back(std::move(edit));
        if (edits_.size() > bound_) {
            edits_.pop_front();
        }
    }

    std::optional<Edit> undo() {
        if (edits_.empty()) {
            return std::nullopt;  // back() on an empty deque is UB
        }
        Edit last = std::move(edits_.back());  // move out before destroying
        edits_.pop_back();
        return last;
    }

    std::size_t size() const { return edits_.size(); }

private:
    std::deque<Edit> edits_;
    std::size_t bound_;
};

#include <stack>
#include <string>

// The adaptor is the right interface: the algorithm only ever needs the
// most recent unmatched opener. It hides iterators deliberately -- if the
// caller had to scan the pending openers, report where an unclosed one
// began, or drop one from the middle, the underlying container would have
// to be used directly instead.
bool brackets_balanced(const std::string& text) {
    std::stack<char> open;
    for (char c : text) {
        if (c == '(' || c == '[' || c == '{') {
            open.push(c);
        } else if (c == ')' || c == ']' || c == '}') {
            if (open.empty()) {
                return false;  // a closer with nothing open; top() would be UB
            }
            const char wanted = (c == ')') ? '(' : (c == ']') ? '[' : '{';
            // pop() returns void and destroys the element, so the value has
            // to be read from top() first.
            if (open.top() != wanted) {
                return false;
            }
            open.pop();
        }
    }
    return open.empty();  // anything still open is unbalanced
}

#include <array>
#include <cstddef>

// Fixed capacity, no heap: std::array stores its elements inside the
// object, so a RingBuffer member allocates nothing and no operation can
// reallocate or invalidate a handle. A std::vector would allocate on its
// first push even with reserve() in the constructor -- reserve moves the
// allocation, it does not remove it. Capacity is part of the type here,
// exactly like the protocol bound it represents.
template <typename T, std::size_t N>
class RingBuffer {
public:
    static_assert(N > 0, "a ring buffer needs at least one slot");

    void push(const T& sample) {
        slots_[(head_ + size_) % N] = sample;
        if (size_ == N) {
            head_ = (head_ + 1) % N;  // full: the oldest slot was overwritten
        } else {
            ++size_;
        }
    }

    std::size_t size() const { return size_; }
    bool full() const { return size_ == N; }

    // Index 0 is the oldest retained sample. Precondition: i < size().
    const T& operator[](std::size_t i) const {
        return slots_[(head_ + i) % N];
    }

private:
    // Braces value-initialise; a bare declaration would leave scalar
    // elements indeterminate until push() wrote over them.
    std::array<T, N> slots_{};
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

static_assert(sizeof(RingBuffer<int, 8>) >= 8 * sizeof(int));
